  for each r in low {
    let o = order "{r.item}" from r.supplier { qty: r.reorder_qty, unit_cost: r.unit_cost }
    if o.amount > $60.00 {
      notify owner "Order for {r.item} from {r.supplier} exceeds $60. Please review."
      stop "order amount exceeds limit"
    }
  }
}
